public class WebViewDetector extends Detector implements XmlScanner {
    public static final Issue ISSUE = Issue.create(
            "WebViewLayout",
            "WebViews in wrap_content parents",
            "The WebView implementation has certain performance optimizations which will not work correctly if the parent view is using `wrap_content` rather than `match_parent`. This can lead to subtle UI bugs.",
            Category.CORRECTNESS,
            4,
            Severity.WARNING,
            new Implementation(WebViewDetector.class, Scope.RESOURCE_FILE_SCOPE));

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.LAYOUT;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList("WebView");
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        Node parentNode = element.getParentNode();
        if (parentNode == null || parentNode.getNodeType() != Node.ELEMENT_NODE) {
            return;
        }
        Element parent = (Element) parentNode;
        if (VALUE_WRAP_CONTENT.equals(parent.getAttributeNS(ANDROID_URI, ATTR_LAYOUT_WIDTH))
                || VALUE_WRAP_CONTENT.equals(parent.getAttributeNS(ANDROID_URI, ATTR_LAYOUT_HEIGHT))) {
            context.report(
                    ISSUE,
                    element,
                    context.getLocation(element),
                    "WebViews in wrap_content parents may not behave correctly");
        }
    }
}
